 const [page,setPage]=useState('Overview'),[range,setRange]=useState('All available periods'),[country,setCountry]=useState('All countries'),[status,setStatus]=useState('Loading Supabase summary'),[aggregateRows,setAggregateRows]=useState([]),[orders,setOrders]=useState([]),[detailsLoaded,setDetailsLoaded]=useState(false),[detailStatus,setDetailStatus]=useState('loading'),[marketingRows,setMarketingRows]=useState([]),[supplierRows,setSupplierRows]=useState([]),[marketRows,setMarketRows]=useState([]),[search,setSearch]=useState(''),[capex,setCapex]=useState(''),[saving,setSaving]=useState(''),[months,setMonths]=useState(''),[productKey,setProductKey]=useState('All products'),[taxRate,setTaxRate]=useState('5'),[showScenario,setShowScenario]=useState(false);
 const db=useMemo(()=>{const u=import.meta.env.VITE_SUPABASE_URL,k=import.meta.env.VITE_SUPABASE_ANON_KEY;return u&&k&&!k.includes('your_')?createClient(u,k):null},[]);
 useEffect(()=>{if(!db){setStatus('Supabase configuration missing');setDetailStatus('unavailable');return}let ok=true;(async()=>{try{const {data:aggData,error:aggError}=await db.from('vw_sales_monthly_by_country').select('month,country,order_count,revenue_inr,total_cost_inr,profit_inr,profit_margin_pct,order_qty,shipped_qty,delayed_order_count,on_time_shipped_orders,dated_shipped_orders').order('month').limit(1000);if(!ok)return;if(aggError){setStatus('Supabase summary unavailable');setDetailStatus('unavailable');return}const initial=aggData||[];setAggregateRows(initial);setStatus(initial.length?'Supabase connected':'Supabase connected — no sales rows');setDetailStatus('loading');const columns='order_id,order_date,ship_due_date,actual_ship_date,buyer_id,buyer_name,country,buyer_tier,product_category,fabric,style_id,supplier_id,order_qty,shipped_qty,revenue_inr,total_cost_inr,profit_inr,profit_margin_pct,delay_days,fabric_cost_per_pc_inr,trims_cost_per_pc_inr,cmt_cost_per_pc_inr,ot_cost_per_pc_inr,overhead_per_pc_inr,rework_cost_inr,freight_cost_inr,late_penalty_inr,actual_efficiency,target_efficiency,rejection_qty,workers,overtime_hours';const detailLoad=(async()=>{try{const ranges=Array.from({length:11},(_,i)=>i*1000);const results=await Promise.all(ranges.map(from=>db.from('fact_orders').select(columns).order('order_id',{ascending:true}).range(from,from+999)));if(!ok)return;const failed=results.find(r=>r.error);if(failed){setDetailStatus('unavailable');return}const rows=results.flatMap(r=>r.data||[]);const uniqueRows=[...new Map(rows.map(r=>[r.order_id,r])).values()];setOrders(uniqueRows);setDetailsLoaded(true);setDetailStatus('loaded')}catch{if(ok)setDetailStatus('unavailable')}})();const lookupLoad=(async()=>{try{const [marketingResult,supplierResult,marketResult]=await Promise.all([db.from('fact_marketing').select('month,country,channel,marketing_spend_inr,inquiries,samples_sent,orders_won,order_value_won_inr').order('month').limit(2000),db.from('dim_suppliers').select('supplier_id,supplier_name,supply_type,avg_delay_days,quality_rating,credit_days').order('supplier_id').limit(100),db.from('dim_market').select('month,cotton_yarn_30s_inr_per_kg,usd_inr').order('month').limit(100)]);if(!ok)return;setMarketingRows(marketingResult.error?[]:(marketingResult.data||[]));setSupplierRows(supplierResult.error?[]:(supplierResult.data||[]));setMarketRows(marketResult.error?[]:(marketResult.data||[]))}catch{if(ok){setMarketingRows([]);setSupplierRows([]);setMarketRows([])}}})();await Promise.all([detailLoad,lookupLoad])}catch{if(ok){setStatus('Supabase connection failed');setDetailStatus('unavailable')}}})();return()=>{ok=false}},[db]);
 const dataConnected=status.startsWith('Supabase connected');
